using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
using SoopaDriveTool.Core;
namespace SoopaDriveTool.Windows;
public partial class MainWindow
{
    void Recovery()
    {
        Note("Recovery reads the source without changing it. Recover files to another disk. Deleted clusters can be reused; exported content needs inspection. Table repair and sector edits require a separate backup and explicit review.");
        int tabStart=body.Children.Count;
        var device=DiskPicker(false,"recovery");var image=new TextBox{IsReadOnly=true};var partitions=new ComboBox{DisplayMemberPath="Name"};var candidates=new ComboBox{DisplayMemberPath="Evidence"};var files=new DataGrid{AutoGenerateColumns=false,MaxHeight=360,SelectionMode=DataGridSelectionMode.Extended};files.Columns.Add(new DataGridTextColumn{Header="Name",Binding=new System.Windows.Data.Binding("Name"),Width=new DataGridLength(2,DataGridLengthUnitType.Star)});files.Columns.Add(new DataGridTextColumn{Header="Bytes",Binding=new System.Windows.Data.Binding("Length")});files.Columns.Add(new DataGridTextColumn{Header="Condition",Binding=new System.Windows.Data.Binding("Condition"),Width=new DataGridLength(3,DataGridLengthUnitType.Star)});var detail=new StackPanel();int sector=512;DiskTable? table=null;
        Stream Open(bool write=false){if(image.Text.Length>0){BackupEngine.RejectExistingAncestorLinks(image.Text);return new FileStream(image.Text,FileMode.Open,write?FileAccess.ReadWrite:FileAccess.Read,write?FileShare.None:FileShare.Read);}if(device.SelectedItem is not DiskInfo d)throw new IOException("Select a source disk or image.");return DiskAccess.Open(d,write,write);}
        async Task CheckSource(){if(image.Text.Length==0&&device.SelectedItem is DiskInfo d){var now=(await StorageService.InventoryAsync()).Single(x=>x.Number==d.Number);QueuePlanner.AssertUnchanged(d,now);sector=d.SectorSize;}}
        async Task<string?> Review(string action)
        {
            await CheckSource();string phrase=image.Text.Length>0?"EDIT IMAGE":"DISK "+((DiskInfo)device.SelectedItem).Number;if(Prompt(action,"This changes the selected source. Type exactly "+phrase+" to apply the reviewed action.")!=phrase)return null;var folder=PickFolder("Choose recovery backup storage on another physical disk");if(folder==null)return null;if(image.Text.Length==0)await DiskAccess.RequireSeparatePathAsync(folder,((DiskInfo)device.SelectedItem).Number);return folder;
        }
        var controls=Stack(T("Recovery source",20,Ink,true),device,T("Or choose a raw image (takes priority)",12,Muted),image,Btn("Choose raw image…",()=>image.Text=PickFile("Raw disk image|*.sdi;*.img;*.bin|All files|*.*")??image.Text),Btn("Use selected physical disk",()=>image.Text=""));
        controls.Children.Add(Btn("Read partition table",async()=>await RunTaskWithActivity("Inspecting partition metadata",async(p,ct)=>{await CheckSource();using var input=Open();table=DiskTables.Read(input,sector);partitions.ItemsSource=table.Partitions;if(partitions.Items.Count>0)partitions.SelectedIndex=0;detail.Children.Clear();detail.Children.Add(Table(table.Partitions,("Partition","Index"),("Offset","Offset"),("Bytes","Length"),("Name","Name")));if(table.RecoveredFromBackup)detail.Children.Add(T("Primary GPT is damaged. The independent backup GPT passed checksums and bounds checks.",13,B("#9C6C20")));}),true));
        controls.Children.Add(Btn("Discover lost partitions",async()=>await RunTaskWithActivity("Discovering lost partitions",async(p,ct)=>{await CheckSource();using var input=Open();candidates.ItemsSource=await Task.Run(()=>DiskRecovery.ScanPartitionsAsync(input,sector,p,ct));if(candidates.Items.Count>0)candidates.SelectedIndex=0;})));
        controls.Children.Add(candidates);controls.Children.Add(Btn("Apply selected partition recovery…",async()=>{if(candidates.SelectedItem is not PartitionCandidate candidate)throw new IOException("Scan and select a candidate.");var folder=await Review("Restore partition entry");if(folder==null)return;await RunTaskWithActivity("Restoring reviewed partition entry",async(p,ct)=>{using var output=Open(true);DiskTable current;try{current=DiskTables.Read(output,sector);}catch(IOException){current=new("GPT",sector,output.Length,Guid.NewGuid(),0,[]);}var next=DiskRecovery.RestoreCandidate(current,candidate);await Data.SaveAsync(Path.Combine(folder,"partition-recovery-"+Guid.NewGuid()+".json"),new{Original=current,Replacement=next,Candidate=candidate});await SaveTableSectors(output,folder,sector);DiskTables.Write(output,next);output.Flush();DiskTables.Read(output,sector);},false);}));
        controls.Children.Add(Btn("Rebuild primary GPT from backup…",async()=>{var folder=await Review("Rebuild GPT");if(folder==null)return;await RunTaskWithActivity("Reconstructing redundant GPT metadata",async(p,ct)=>{using var output=Open(true);var current=DiskTables.Read(output,sector);if(current.Style!="GPT"||!current.RecoveredFromBackup)throw new IOException("A valid backup GPT and damaged primary are required.");await SaveTableSectors(output,folder,sector);DiskTables.Write(output,current);output.Flush();if(DiskTables.Read(output,sector).RecoveredFromBackup)throw new IOException("Primary GPT verification failed.");},false);}));body.Children.Add(Card(controls));body.Children.Add(detail);
        var recover=Stack(T("Deleted-file recovery",20,Ink,true),T("Select a partition after reading its table. NTFS uses deleted MFT records and data runs. FAT32 uses deleted directory entries. Signature carving searches contiguous PNG, JPEG and PDF content.",12,Muted),partitions);var row=new WrapPanel();
        void Scan(string text,int method)=>row.Children.Add(Btn(text,async()=>await RunTaskWithActivity(text,async(p,ct)=>{await CheckSource();using var input=Open();var part=partitions.SelectedItem as TablePartition;long start=part?.Offset??0,length=part?.Length??input.Length;List<RecoverableFile> results=method==0?await Task.Run(()=>DiskRecovery.ScanNtfsDeletedAsync(input,start,length,progress:p,ct:ct)):method==1?await Task.Run(()=>DiskRecovery.ScanFatDeletedAsync(input,start,length,p,ct)):await Task.Run(()=>DiskRecovery.CarveAsync(input,start,length,progress:p,ct:ct));files.ItemsSource=results;})));
        Scan("Find deleted NTFS files",0);Scan("Find deleted FAT32 files",1);Scan("Carve file signatures",2);recover.Children.Add(row);recover.Children.Add(files);
        recover.Children.Add(Btn("Preview selected bytes",async()=>{if(files.SelectedItem is not RecoverableFile file)throw new IOException("Select a candidate.");using var input=Open();byte[] bytes=file.Resident??(file.Extents.Count>0?DiskTables.ReadAt(input,file.Extents[0].Offset,(int)Math.Min(4096,Math.Min(file.Length,file.Extents[0].Length))):[]);var text=Convert.ToHexString(bytes.AsSpan(0,Math.Min(bytes.Length,4096)));Prompt("Recovery preview",file.Condition+"\nFirst bytes (hex)",text);}));
        recover.Children.Add(Btn("Export selected files…",async()=>{var selected=files.SelectedItems.Cast<RecoverableFile>().ToList();if(selected.Count==0)throw new IOException("Select one or more candidates.");var folder=PickFolder("Recover files to a different disk");if(folder==null)return;if(image.Text.Length==0)await DiskAccess.RequireSeparatePathAsync(folder,((DiskInfo)device.SelectedItem).Number);else if(Path.GetPathRoot(folder)==Path.GetPathRoot(image.Text))throw new IOException("Recover to a different volume to avoid overwriting recoverable content.");await RunTaskWithActivity("Exporting recovered files",async(p,ct)=>{await CheckSource();using var input=Open();int done=0;foreach(var file in selected){await DiskRecovery.ExportAsync(input,file,Path.Combine(folder,DiskRecovery.SafeName(file.Name)),ct);p.Report(new("Exporting candidates",100.0*++done/selected.Count,file.Name+" · "+file.Condition));}});},true));body.Children.Add(Card(recover));
        var offset=new TextBox{Text="0"};var hex=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=100,MaxHeight=220,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};string expected="";long previewOffset=-1;var editor=Stack(T("Sector preview and reviewed editor",20,Ink,true),T("Byte offset (whole sectors). Reads one sector; the original SHA-256 must still match when you apply.",12,Muted),offset,Btn("Read sector",async()=>{await CheckSource();if(!long.TryParse(offset.Text,out long n)||n<0||n%sector!=0)throw new IOException("Enter an aligned byte offset.");using var input=Open();var bytes=DiskTables.ReadAt(input,n,sector);expected=Convert.ToHexString(SHA256.HashData(bytes));previewOffset=n;hex.Text=Convert.ToHexString(bytes);}),hex);
        editor.Children.Add(Btn("Apply reviewed sector bytes…",async()=>{if(!long.TryParse(offset.Text,out long n)||n!=previewOffset||expected.Length==0)throw new IOException("Read the target sector first.");var replacement=Convert.FromHexString(string.Concat(hex.Text.Where(c=>!char.IsWhiteSpace(c))));if(replacement.Length!=sector)throw new IOException("Replacement must have the same sector length.");var folder=await Review("Write sector bytes");if(folder==null)return;await RunTaskWithActivity("Writing reviewed sector",async(p,ct)=>{using var output=Open(true);await DiskRecovery.WriteSectorAsync(output,n,replacement,expected,Path.Combine(folder,"sector-"+n+"-"+Guid.NewGuid()+".bin"),sector,ct);},false);}));body.Children.Add(Card(editor));TabWorkspace(tabStart,("Partitions",2),("Deleted files",1),("Sector editor",1));
    }
    static async Task SaveTableSectors(Stream disk,string folder,int sector)
    {string id=Guid.NewGuid().ToString("N");await File.WriteAllBytesAsync(Path.Combine(folder,"table-start-"+id+".bin"),DiskTables.ReadAt(disk,0,(int)Math.Min(disk.Length,1024*1024)));await File.WriteAllBytesAsync(Path.Combine(folder,"table-end-"+id+".bin"),DiskTables.ReadAt(disk,Math.Max(0,disk.Length-1024*1024),(int)Math.Min(disk.Length,1024*1024)));}
}
